function [p] = coil_power(a, m_max, p_max)
%COIL_POWER  The power [W] of a coil whose dipole averaged a over the step, of largest dipole m_max drawing p_max there.
%   a: real[1] (passed a plain number)
%   m_max: real[1] (passed a plain number)
%   p_max: real[1] (passed a plain number)
%   returns p: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    p = 0;
    p = ((asils.pc.fabs(a) / m_max) * p_max);
end
